n":1,"retry_semantics":"retry_safe","safety_level":"safe","schema":{"additionalProperties":false,"properties":{"num_iid":{"type":"string"},"product_code":{"type":"string"}},"required":[],"type":"object"},"schema_hash":"870b188309e49e3e875d081fc9aa5ab0c2364f2fed4ec2c00996c789a72d0140","side_effect":"none","tool_group":"erp_local"},{"allowed_channels":["web","wecom"],"allowed_scope_kinds":["channel"],"authorization_requirement":"none","cancel_semantics":"unsupported","canonical_name":"local_product_identify","capability_requirements":["erp.local.product_identify"],"description":"编码识别与商品搜索。毫秒级响应。三种模式：编码精确匹配（返回1条）、商品名模糊搜索（返回最多20条）、规格名模糊搜索（返回最多20条）。返回编码/名称/规格/条码/供应商。code/name/spec 至少传一个。⚠ 返回多条匹配时，必须列出候选让用户确认目标商品，禁止自行选择第一条。相关工具：识别到编码后可用 local_stock_query 查库存、local_data 查订单/采购/售后、local_product_stats 查统计。","executor_revision":1,"executor_type":"runtime_read:local_product_identify","provider_revision":"provider-v1","provider_schema":{"properties":{"code":{"description":"商品编码/SKU编码/条码（精确匹配）","type":"string"},"name":{"description":"商品名称关键词（模糊搜索）","type":"string"},"spec":{"description":"规格名称关键词（模糊搜索，如'红色''120g'）","type":"string"}},"required":[],"type":"object"},"provider_schema_hash":"11afa38d6600ed9df9dfd3ecca8009fcab276fa233d21c6727b059e28c5a6a2e","reconcile_semantics":"unsupported","result_schema_revision":1,"retry_semantics":"retry_safe","safety_level":"safe","schema":{"additionalProperties":false,"properties":{"code":{"type":"string"},"name":{"type":"string"},"spec":{"type":"string"}},"required":[],"type":"object"},"schema_hash":"4c85accacc3a4c745d16250fefbe8a07205a5421550d2fdc63a9102761fd3d2e","side_effect":"none","tool_group":"erp_local"},{"allowed_channels":["web","wecom"],"allowed_scope_kinds":["channel"],"authorization_requirement":"none","cancel_semantics":"unsupported","canonical_name":"local_product_stats","capability_requirements":["erp.local.product_stats"],"description":"按商品编码查统计报表（日/周/月维度）。毫秒级响应。返回聚合指标：订单数/销量/销售额、采购数/采购额、售后数/退货数。支持日期范围对比。⚠ 需精确编码，模糊时先 local_product_identify。相关工具：全局统计（不按商品）用 local_data(mode=summary)；查供应链流转用 local_data 按 doc_type 分查。","executor_revision":1,"executor_type":"runtime_read:local_product_stats","provider_revision":"provider-v1","provider_schema":{"additionalProperties":false,"properties":{"end_date":{"type":"string"},"product_code":{"type":"string"},"start_date":{"type":"string"}},"required":["product_code"],"type":"object"},"provider_schema_hash":"1003a77431d8ad96c5e1f6c3c0eca08a9b9cb087f0a65bce236724c934b73249","reconcile_semantics":"unsupported","result_schema_revision":1,"retry_semantics":"retry_safe","safety_level":"safe","schema":{"additionalProperties":false,"properties":{"end_date":{"type":"string"},"product_code":{"type":"string"},"start_date":{"type":"string"}},"required":["product_code"],"type":"object"},"schema_hash":"1003a77431d8ad96c5e1f6c3c0eca08a9b9cb087f0a65bce236724c934b73249","side_effect":"none","tool_group":"erp_local"},{"allowed_channels":["web","wecom"],"allowed_scope_kinds":["channel"],"authorization_requirement":"none","cancel_semantics":"unsupported","canonical_name":"local_shop_list","capability_requirements":["erp.local.shop_list"],"description":"查询店铺列表（含所有店铺，包括新开未出单的）。毫秒级响应。返回店铺名称/平台/状态/ID，按平台分组显示。支持按平台过滤（如只看拼多多店铺）。适合：有哪些店铺、拼多多店铺列表、各平台店铺等查询。相关工具：拿到店铺名后可用 local_data(mode=summary, shop_name=...) 统计该店铺数据。","executor_revision":1,"executor_type":"runtime_read:local_shop_list","provider_revision":"provider-v1","provider_schema":{"additionalProperties":false,"properties":{"platform":{"type":"string"}},"required":[],"type":"object"},"provider_schema_hash":"81ea60c206854762e0d52bbdb7427e5efaf8d88c8e231e50463a10f646a7e4dd","reconcile_semantics":"unsupported","result_schema_revision":1,"retry_semantics":"retry_safe","safety_level":"safe","schema":{"additionalProperties":false,"properties":{"platform":{"type":"string"}},"required":[],"type":"object"},"schema_hash":"81ea60c206854762e0d52bbdb7427e5efaf8d88c8e231e50463a10f646a7e4dd","side_effect":"none","tool_group":"erp_local"},{"a