n_requirement":"none","cancel_semantics":"unsupported","canonical_name":"get_conversation_context","capability_requirements":["runtime.conversation.read"],"description":"获取当前对话的最近消息记录","executor_revision":1,"executor_type":"runtime_read:get_conversation_context","provider_revision":"provider-v1","provider_schema":{"additionalProperties":false,"properties":{"limit":{"type":"integer"}},"required":[],"type":"object"},"provider_schema_hash":"16986a66e5924b0c9c609019112350948a47c0a6f9247b9419330aded057df8c","reconcile_semantics":"unsupported","result_schema_revision":1,"retry_semantics":"retry_safe","safety_level":"safe","schema":{"additionalProperties":false,"properties":{"limit":{"type":"integer"}},"required":[],"type":"object"},"schema_hash":"16986a66e5924b0c9c609019112350948a47c0a6f9247b9419330aded057df8c","side_effect":"none","tool_group":"runtime"},{"allowed_channels":["web","wecom"],"allowed_scope_kinds":["channel","user"],"authorization_requirement":"explicit_intent","cancel_semantics":"best_effort","canonical_name":"image_agent","capability_requirements":["runtime.child_run.create"],"description":"生成单张电商商品图片（白底主图、场景氛围图、详情页卖点图、SKU 展示图），输出符合目标平台规范。每次 1 张，前端自动展示。\n\nGuidelines:\n- 有 image_task_meta 时按 images[i].description 逐项调用，每张完成后简短确认即可。\n- 生成后不要描述图片内容，不要问后续问题，不要提及下载。\n- 生成失败时前端自动显示重试按钮，不需要道歉或额外处理。\n- image_urls 和 style 由系统自动注入，不需要传这两个参数。\n- 非电商画图（插画/logo/创意图）→ 用 generate_image，不要用此工具。\n- 局部修图（抠图/换背景）→ 不支持。","executor_revision":1,"executor_type":"runtime_child_run:image_agent","provider_revision":"provider-v1","provider_schema":{"additionalProperties":false,"properties":{"product_id":{"type":"string"},"prompt":{"type":"string"}},"required":["prompt"],"type":"object"},"provider_schema_hash":"4511a2bfdef730daa0980e095c0e82d423ec7cccb27f3af7abd3915d77304539","reconcile_semantics":"executor_defined","result_schema_revision":1,"retry_semantics":"reconcile_only","safety_level":"confirm","schema":{"additionalProperties":false,"properties":{"product_id":{"type":"string"},"prompt":{"type":"string"}},"required":["prompt"],"type":"object"},"schema_hash":"4511a2bfdef730daa0980e095c0e82d423ec7cccb27f3af7abd3915d77304539","side_effect":"external","tool_group":"composite"},{"allowed_channels":["web","wecom"],"allowed_scope_kinds":["channel","user"],"authorization_requirement":"explicit_intent","cancel_semantics":"best_effort","canonical_name":"local_data","capability_requirements":["artifact.materialize"],"description":"本地数据库统一查询工具。支持查询/统计/导出 ERP 全部业务表数据。\n除单据表外还支持：库存(stock)、商品(product)、SKU(sku)、日统计(daily_stats)、平台映射(platform_map)、批次库存(batch_stock)、订单日志(order_log)、售后日志(aftersale_log)。\n用 filters 数组指定过滤条件，任意字段组合均可。\n\n常用字段：\n- order_status/doc_status: 状态(WAIT_AUDIT/WAIT_SEND_GOODS/SELLER_SEND_GOODS/FINISHED/CLOSED)\n- consign_time: 发货时间  |  pay_time: 付款时间  |  doc_created_at: 创建时间\n- shop_name: 店铺名  |  platform: 平台(tb/jd/pdd/fxg/kuaishou/xhs/1688)\n- outer_id: 商品主编码  |  sku_outer_id: SKU编码  |  item_name: 商品名称\n- order_no: 平台订单号  |  express_no: 快递单号\n- supplier_name: 供应商  |  warehouse_name: 仓库\n- amount: 金额  |  pay_amount: 实付金额  |  quantity: 数量\n- cost: 成本  |  gross_profit: 毛利润  |  price: 单价\n- post_fee: 运费  |  discount_fee: 优惠金额  |  refund_money: 退款金额\n- is_scalping: 是否刷单/空包(0=正常,1=刷单)  |  is_exception: 是否异常订单(0/1)\n- is_refund: 是否退款(0/1)  |  is_cancel: 是否取消(0/1)\n- aftersale_type: 售后类型(0~9)  |  refund_status: 退款状态  |  text_reason: 售后原因\n- buyer_nick: 买家昵称  |  status_name: 状态中文名\n\nop: eq(等于) ne(不等于) gt(大于) gte(>=) lt(<) lte(<=) in(在列表中) like(模糊) is_null(是否空) between(区间)\n\n示例1：4月14日已发货订单列表\n  doc_type=order, mode=detail, filters=[\n    {\"field\":\"order_status\",\"op\":\"eq\",\"value\":\"SELLER_SEND_GOODS\"},\n    {\"field\":\"consign_time\",\"op\":\"gte\",\"value\":\"2026-04-14 00:00:00\"},\n    {\"field\":\"consign_time\",\"op\":\"lt\",\"value\":\"2026-04-15 00:00:00\"}]\n\n示例2：淘宝金额>500订单按店铺统计\n  doc_type=order, mode=summary, filters=[\n    {\"field\":\"platform\",\"op\":\"eq\",\"value\":\"tb\"},\n    {\"field\":\"amount\",\"op\":\"gt\",\"value\":500}],\n  group_by=[\"shop_name\"]\n\n示例3：导出3月拼多多发货订单\n  doc_type=order, mode=export, filters=[...],\n  fields=[\"order_no\",\"amount\",\"consign_time\"]","executor_revision":1,"executor_type":"runtime_artifact_job:local_data","provider_revision":"provider-v1","provider_schema":{"additionalProperties":false,"properties":{"alert_type":{"type":"string"},"compare_range":{"type":"string"},"doc_type":{"enum":["order","purchase","aftersale","receipt","shelf","purchase_return","stock","daily_stats"],"type":"string"},"extra_fields":{"items":{"type":"string"},"type":"array"},"filters":{"type":"array"},"group_by":{"items":{"type":"string"},"type":"array"},"limit":{"maximum":200,"minimum":1,"type":"integer"},"metrics":{"items":{"type":"string"},"type":"array"},"mode":{"type":"string"},"query_type":{"enum":["trend","compare","cross","distribution"],"type":"string"},"sort_by":{"type":"string"},"sort_dir":{"enum":["asc","desc"],"type":"string"},"time_granularity":{"type":"string"},"time_type":{"type":"string"}},"required":["doc_type","query_type"],"type":"object"},"provider_schema_hash":"506b722228098ee1ce7d3e07244f186ccdf3897278e7e1d1e7b8ed6cf2aa8303","reconcile_semantics":"executor_defined","result_schema_revision":1,"retry_semantics":"reconcile_only","safety_level":"safe","schema":{"additionalProperties":false,"properties":{"alert_type":{"type":"string"},"compare_range":{"type":"string"},"doc_type":{"enum":["order","purchase","aftersale","receipt","shelf","purchase_return","stock","daily_stats"],"type":"string"},"extra_fields":{"items":{"type":"string"},"type":"array"},"filters":{"type":"array"},"group_by":{"items":{"type":"string"},"type":"array"},"limit":{"maximum":200,"minimum":1,"type":"integer"},"metrics":{"items":{"type":"string"},"type":"array"},"mode":{"type":"string"},"query_type":{"enum":["trend","compare","cross","distribution"],"type":"string"},"sort_by":{"type":"string"},"sort_dir":{"enum":["asc","desc"],"type":"string"},"time_granularity":{"type":"str